// گام ۱ — بررسی توکن و ساختن پرامپت «داور جلسه‌ی دفاع آزمایشی».
// مدل پاسخ دانشجو را فقط با تکه‌ای از پایان‌نامه که پرسش از آن آمده مقایسه می‌کند.
const req = $input.first().json;
if (!$env.AGENT_TOKEN || (req.headers || {})['x-agent-token'] !== $env.AGENT_TOKEN) {
  throw new Error('Unauthorized: invalid X-Agent-Token');
}
const b = req.body || {};
const history = (Array.isArray(b.previous_turns) ? b.previous_turns : [])
  .map((t) => `پرسش: ${t.question}\nپاسخ پیشین دانشجو: ${t.answer}\nبازخورد: ${t.feedback}`)
  .join('\n\n');
const system = [
  'تو داور جلسه‌ی دفاع آزمایشی پروژه‌ی کارشناسی مهندسی کامپیوتر هستی و پاسخ دانشجو را ارزیابی می‌کنی تا برای جلسه‌ی واقعی آماده شود.',
  'قواعد:',
  '۱. پاسخ را فقط با «تکه‌ی پایان‌نامه» و دانش عمومی رشته بسنج؛ چیزی به پایان‌نامه نسبت نده که در تکه نیامده است.',
  '۲. verdict یکی از strong (کامل، دقیق و مستند)، partial (درست ولی ناقص یا کلی)، weak (نادرست، مبهم یا بی‌ربط) باشد.',
  '۳. feedback دو تا چهار جمله‌ی سازنده و مشخص به فارسی و خطاب به دانشجو باشد.',
  '۴. missing حداکثر سه نکته‌ی مشخص است که بهتر بود در پاسخ می‌آمد (اگر پاسخ کامل است خالی بگذار).',
  '۵. follow_up یک پرسش تکمیلی کوتاه است که داور واقعی پس از شنیدن این پاسخ می‌پرسد.',
  'خروجی فقط یک شیء JSON با همین شکل:',
  '{"verdict": "partial", "feedback": "...", "missing": ["..."], "follow_up": "..."}',
].join('\n');
return [{
  json: {
    result_path: b.result_path,
    llm_request: {
      model: $env.LLM_CHAT_MODEL,
      temperature: 0.2,
      stream: false,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: system },
        {
          role: 'user',
          content:
            `عنوان پروژه: ${(b.case || {}).title_fa || ''}\nدسته‌ی پرسش: ${b.category || ''}\n` +
            `چرا این پرسش مهم است: ${b.why || ''}\n\n` +
            `تکه‌ی پایان‌نامه:\n"""\n${String(b.thesis_excerpt || '').slice(0, 3000)}\n"""\n\n` +
            (history ? `نوبت‌های پیشین همین پرسش:\n${history}\n\n` : '') +
            `پرسش داور: ${b.question || ''}\n\nپاسخ دانشجو:\n"""\n${b.answer || ''}\n"""`,
        },
      ],
    },
  },
}];

// گام ۳ — خواندن خروجی مدل. هر چیز نامعتبر به «خطای عامل» تبدیل می‌شود، نه به بازخورد ساختگی.
const path = $('Build Prompt').first().json.result_path;
const model = $env.LLM_CHAT_MODEL;
const res = $input.first().json || {};
const content = res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content;
let result;
try {
  if (!content) throw new Error((res.error && (res.error.message || JSON.stringify(res.error))) || 'پاسخ خالی از مدل');
  const clean = String(content).replace(/<think>[\s\S]*?<\/think>/g, '');
  const parsed = JSON.parse(clean.slice(clean.indexOf('{'), clean.lastIndexOf('}') + 1));
  result = {
    verdict: String(parsed.verdict || '').toLowerCase().trim(),
    feedback: String(parsed.feedback || ''),
    missing: Array.isArray(parsed.missing) ? parsed.missing.map(String) : [],
    follow_up: String(parsed.follow_up || ''),
    model,
  };
} catch (e) {
  result = { error: 'مدل زبانی بازخورد قابل‌استفاده‌ای نداد.', detail: String(e.message || e).slice(0, 300), model };
}
return [{ json: { result_path: path, result } }];
